def logfile_line_result(wait, line, params):
    """Write the line to a logfile, print progress."""
    # pylint: disable=pointless-statement
    if params["trace"] and wait > 0 and line is None:
        progress("sj" + str(wait))
        return True
    if isinstance(line, tuple):
        if params["trace"]:
            logging.debug("e: %s", str(line[0], "utf-8").rstrip())
        sys.stdout.buffer.write(line[0])
        params["output"].write(line[0])
    return True

def enqueue_output(fd, queue, instance, identifier, params):
    """add stdout/stderr to the specified queue"""
    while True:
        try:
            data = os.read(fd, 1024)
        except OSError as ex:
            print_log(
                f"{identifier} communication line seems to be closed: {str(ex)}", params
            )
            break
        if not data:
            break
        queue.put((data, instance))
    print(f"{identifier} done! {params}")
    print_log(f"{identifier} done!", params)
    queue.put(-1)
    os.close(fd)

def convert_result(result_array):
    """binary -> string"""
    result = ""
    for one_line in result_array:
        if isinstance(one_line, str):
            result += "\n" + one_line.rstrip()
        else:
            result += "\n" + one_line.decode("utf-8").rstrip()
    return result

def add_message_to_report(params, string, print_it=True, add_to_error=False):
    """add a message from python to the report strings/files + print it"""
    oskar = "OSKAR"
    count = int(80 / len(oskar))
    datestr = f"  {datetime.now()} - "
    offset = 80 - (len(string) + len(datestr) + 2 * len(oskar))
    if print_it:
        logging.info(string)
        # we also want these messages to be written to stdout, so they also show up in CircleCI
        print(string)
    if add_to_error:
        params["error"] += "async_client.py: " + string + "\n"
    if isinstance(params["output"], list):
        params[
            "output"
        ] += f"{oskar*count}\n{oskar}{datestr}{string}{' '*offset}{oskar}\n{oskar*count}\n"
    else:
        params["output"].write(
            bytearray(
                f"{oskar*count}\n{oskar}{datestr}{string}{' '*offset}{oskar}\n{oskar*count}\n",
                "utf-8",
            )
        )
        params["output"].flush()
    sys.stdout.flush()
    return string + "\n"

def kill_children(identifier, params, children):
    """slash all processes enlisted in children - if they still exist"""
    err = ""
    killed = []
    for one_child in children:
        if one_child.pid in killed:
            continue
        try:
            pname = one_child.name()
            if pname not in ["svchost.exe", "conhost.exe", "mscorsvw.exe"]:
                killed.append(one_child.pid)
                err += add_message_to_report(
                    params,
                    f"{identifier}: killing {pname} - {str(one_child.pid)}",
                )
                one_child.resume()
        except FileNotFoundError:
            pass
        except AttributeError:
            pass
        except ProcessLookupError:
            pass
        except psutil.NoSuchProcess:
            pass
        except psutil.AccessDenied:
            pass
        try:
            one_child.send_signal(signal.SIGBUS)
        except psutil.NoSuchProcess:  # pragma: no cover
            pass
    print_log(
        f"{identifier}: Waiting for the children to terminate {killed} {len(children)}",
        params,
    )
    psutil.wait_procs(children, timeout=20)
    return err

def expect_failure(expect_to_fail, ret, params):
    """convert results, throw error if wanted"""
    attach(str(ret["rc_exit"]), f"Exit code: {str(ret['rc_exit'])} == {expect_to_fail}")
    res = (None, None, None, None)
    if ret["have_deadline"] or ret["progressive_timeout"]:
        res = (False, convert_result(params["output"]), 0, ret["line_filter"])
        raise CliExecutionException(
            "Execution failed.", res, ret["progressive_timeout"] or ret["have_deadline"]
        )
    if ret["rc_exit"] != 0:
        res = (False, convert_result(params["output"]), 0, ret["line_filter"])
        if expect_to_fail:
            return res
        raise CliExecutionException("Execution failed.", res, False)

    if not expect_to_fail:
        if len(params["output"]) == 0:
            res = (True, "", 0, ret["line_filter"])
        else:
            res = (True, convert_result(params["output"]), 0, ret["line_filter"])
        return res

    if len(params["output"]) == 0:
        res = (True, "", 0, ret["line_filter"], params["error"])
    else:
        res = (True, convert_result(params["output"]), 0, ret["line_filter"])
    raise CliExecutionException(
        f"{params.identifier} Execution was expected to fail, but exited successfully.",
        res,
        ret["progressive_timeout"],
    )

def ascii_convert(the_bytes: bytes):
    """convert string to only be ascii without control sequences"""
    return ANSI_ESCAPE_B.sub(rb"", the_bytes).decode("utf-8")

def ascii_convert_str(the_str: str):
    """convert string to only be ascii without control sequences"""
    return ANSI_ESCAPE.sub(rb"", the_str)

def list_all_processes():
    """list all processes for later reference"""
    pseaf = "PID  Process"
    # pylint: disable=catching-non-exception
    for process in psutil.process_iter(["pid", "ppid", "name"]):
        if  process.pid in [1, 2] or process.ppid() == 2:
            continue
        cmdline = process.name
        try:
            cmdline = str(process.cmdline())
            if cmdline == "[]":
                cmdline = "[" + process.name() + "]"
        except psutil.AccessDenied:
            pass
        except psutil.ProcessLookupError:
            pass
        except psutil.NoSuchProcess:
            pass
        logging.info("PID: %s PPID: %s %s", process.pid, process.ppid(), cmdline)
    logging.info(pseaf)
    sys.stdout.flush()

def kill_all_arango_processes():
    """list all processes for later reference"""
    # pylint: disable=catching-non-exception
    for process in psutil.process_iter(["pid", "name"]):
        if (
            process.name().lower().find("arango") >= 0
            or process.name().lower().find("tshark") >= 0
        ):
            try:
                logging.info("Main: killing %s - %s", process.name(), str(process.pid))
                process.resume()
            except psutil.NoSuchProcess:
                pass
            except psutil.AccessDenied:
                pass
            try:
                process.kill()
            except psutil.NoSuchProcess:  # pragma: no cover
                pass

def gather_process_thread_statistics(p):
    """ gather the statistics of one process and all its threads """
    ret = {}
    ret['process'] = [{
        'time': time.ctime(),
        'pid': p.pid,
        'ppid': p.ppid(),
        'cmdline': p.cmdline(),
        'name': p.name(),
        'percent': p.cpu_percent(),
        'iocounters': p.io_counters(),
        'ctxSwitches': p.num_ctx_switches(),
        'numfds': p.num_fds(),
        'cpu_times': p.cpu_times(),
        'meminfo': p.memory_full_info(),
        'netcons': p.connections()
    }]
    for t in p.threads():
        ret[ t.id ] = { 'user': t.user_time, 'sys': t.system_time}
    return ret

def add_delta(p1, p2):
    """ calculate and add a delta in cpu and time to all threads of a process """
    tids = list(p1.keys())
    for tid in tids:
        if tid in p2 and tid != 'process':
            p1[tid]['d_user'] = p2[tid]['user'] - p1[tid]['user']
            p1[tid]['d_sys'] = p2[tid]['sys'] - p1[tid]['sys']
    p1['process'].append(p2['process'][0])

def get_all_processes_stats_json(load):
    """ aggregate a structure of all processes and their threads plus delta """
    # pylint: disable=broad-exception-caught
    process_full_list = {}
    process_full_list['sys'] = {
        'load': load,
        'vmem': psutil.virtual_memory(),
        'mem': psutil.swap_memory(),
        'diskio': psutil.disk_io_counters(perdisk=True, nowrap=True),
        'netio': psutil.net_io_counters(pernic=True, nowrap=True),
    }
    processes = psutil.process_iter()
    for process in processes:
        name = ""
        try:
            name = process.name()
            if  process.pid not in [1, 2] and process.ppid() != 2:
                procstat = gather_process_thread_statistics(process)
                process_full_list[f"p{process.pid}"] = procstat
        except psutil.AccessDenied:
            pass
        except Exception as ex:
            print(f"while inspecting {name}: {ex} ")
    return json.dumps(process_full_list)

