            "httpConnections": {
             "description": "the number of open http connections\n",
             "type": "integer"
            },
            "ioTime": {
             "description": "IO Time\n",
             "properties": {
              "count": {
               "description": "number of values summarized\n",
               "type": "integer"
              },
              "counts": {
