      "description": "The name of the user.\n",
      "in": "path",
      "name": "user",
      "required": true,
      "schema": {
       "type": "string"
      }
     },
     {
      "description": "The name of the database.\n",
      "in": "path",
      "name": "dbname",
      "required": true,
      "schema": {
       "type": "string"
      }
     }
    ],
    "responses": {
     "202": {
      "description": "Returned if the access permissions were changed successfully.\n"
